// Do not edit this file as it will be overwritten if HAMR codegen is rerun

/* HAMR coverage report.  Draws the report from window.HAMR_COVERAGE, which
 * coverage-report.cmd writes to data.js:
 *
 *   { crate: the crate's name, or the crates' names joined by ", ",
 *     root: the crates' directory (paths are shown relative to it),
 *     date: milliseconds since the epoch,
 *     lcov: `llvm-cov export -format=lcov` output (per-line execution counts),
 *     llvm: `llvm-cov export -format=text -skip-functions` output (per-file summaries
 *           of lines, regions, functions and branches; branch records with columns;
 *           region segments),
 *     sources: { <file name as llvm-cov gives it>: <file text> } }
 *
 * Views, selected by the URL fragment: the top level (#), a directory (#dir=<dir>)
 * and a source file (#file=<path>, optionally &line=<n>).  Directories are listed
 * flat, each holding the files directly in it. */
(function () {
  'use strict';
  var C = window.HAMR_COVERAGE;
  var app = document.getElementById('app');
  if (!C) { app.textContent = 'No coverage data: data.js is missing or failed to load.'; return; }

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined) e.textContent = text;
    return e;
  }
  function link(text, href, cls) { var a = el('a', cls, text); a.href = href; return a; }
  function norm(p) { return String(p).replace(/\\/g, '/'); }
  function dirOf(p) { var i = p.lastIndexOf('/'); return i < 0 ? '.' : p.slice(0, i); }
  function baseOf(p) { return p.slice(p.lastIndexOf('/') + 1); }
  function pct(hit, total) { return total ? Math.round(1000 * hit / total) / 10 : NaN; }
  // genhtml's default limits: green from 90 %, yellow from 75 %
  function level(p) { return p >= 90 ? 'hi' : p >= 75 ? 'med' : 'lo'; }

  // ---- model ----
  var root = norm(C.root || '').replace(/\/$/, '');
  function rel(p) { p = norm(p); return root && p.indexOf(root + '/') === 0 ? p.slice(root.length + 1) : p; }

  var lineCounts = {};  // normalized file name -> { line: count }
  var cur = null;
  C.lcov.split(/\r?\n/).forEach(function (l) {
    if (l.indexOf('SF:') === 0) { cur = {}; lineCounts[norm(l.slice(3))] = cur; }
    else if (l.indexOf('DA:') === 0 && cur) { var p = l.slice(3).split(','); cur[+p[0]] = +p[1]; }
    else if (l === 'end_of_record') cur = null;
  });

  // The never-executed code regions of each line, from llvm's segments
  // ([line, col, count, hasCount, isRegionEntry, isGapRegion]): a segment runs to the
  // next; one with a count of 0 that is not a gap is code that never ran.  Columns
  // are 1-based; an end of 0 runs to the end of the line.
  function zeroSpans(segments) {
    var spans = {};
    for (var i = 0; i + 1 < segments.length; i++) {
      var s = segments[i], n = segments[i + 1];
      if (!s[3] || s[5] || s[2] !== 0) continue;
      for (var ln = s[0]; ln <= n[0]; ln++) {
        var a = ln === s[0] ? s[1] : 1, b = ln === n[0] ? n[1] : 0;
        if (ln === n[0] && b === 1) continue;
        (spans[ln] = spans[ln] || []).push([a, b]);
      }
    }
    return spans;
  }

  var files = [];
  var byPath = {};
  C.llvm.data.forEach(function (d) {
    d.files.forEach(function (f) {
      var path = rel(f.filename), s = f.summary;
      var br = {};
      (f.branches || []).forEach(function (b) { (br[b[0]] = br[b[0]] || []).push(b); });
      Object.keys(br).forEach(function (k) { br[k].sort(function (x, y) { return x[1] - y[1]; }); });
      var file = {
        path: path, dir: dirOf(path), name: baseOf(path),
        src: C.sources[f.filename] || '',
        lines: lineCounts[norm(f.filename)] || {},
        m: { line: [s.lines.covered, s.lines.count], region: [s.regions.covered, s.regions.count],
             func: [s.functions.covered, s.functions.count], branch: [s.branches.covered, s.branches.count] },
        br: br, z: zeroSpans(f.segments || [])
      };
      files.push(file);
      byPath[path] = file;
    });
  });
  var dirs = {};
  files.forEach(function (f) { (dirs[f.dir] = dirs[f.dir] || []).push(f); });
  function total(fs) {
    var t = { line: [0, 0], region: [0, 0], func: [0, 0], branch: [0, 0] };
    fs.forEach(function (f) { Object.keys(t).forEach(function (k) { t[k][0] += f.m[k][0]; t[k][1] += f.m[k][1]; }); });
    return t;
  }
  var date = C.date ? new Date(C.date).toLocaleString() : '';
  document.title = (C.crate ? C.crate + ' ' : '') + 'coverage';

  // ---- help ----
  var METRICS = [['line', 'Lines', 'lines'], ['region', 'Regions', 'regions'], ['func', 'Functions', 'functions'], ['branch', 'Branches', 'branches']];
  var HELP = {
    line: 'Lines: share of executable lines that ran at least once. A line counts as covered if any code on it ran, even if part of it did not.',
    region: 'Regions: share of code regions that ran. A region is a stretch of code that runs as a whole (an if or else body, a match arm, a loop body, each && / || operand after the first, code after an early return or ?), so regions catch unexecuted code inside a covered line.',
    func: 'Functions: share of functions entered at least once.',
    branch: 'Branches: each if condition, and each && / || operand, has a true and a false outcome; this is the share of outcomes taken. match arms count as regions, not branches.'
  };
  function helpPanel() {
    var overlay = el('div', 'gl-help-overlay');
    var box = el('div', 'gl-help');
    var close = link('×', '#', 'gl-help-close');
    box.appendChild(close);
    box.appendChild(el('h2', '', 'Reading this coverage report'));
    function section(title, items) {
      box.appendChild(el('h3', '', title));
      var dl = el('dl');
      items.forEach(function (it) { dl.appendChild(el('dt', '', it[0])); dl.appendChild(el('dd', '', it[1])); });
      box.appendChild(dl);
    }
    section('The four measures', [
      ['Lines', 'Executable lines that ran at least once. Coarse: a line is covered if any code on it ran, even if part of it never did.'],
      ['Regions', 'LLVM\'s own unit: a stretch of code that runs as a whole once entered -- an if or else body, a match arm, a loop body, each operand of && or || after the first, the code after an early return or ?. A line can hold several regions, and a region can span lines, so region and line percentages differ. Region coverage is what shows code that never ran inside a line that did.'],
      ['Functions', 'Functions entered at least once. The coarsest measure.'],
      ['Branches', 'Each if condition, and each operand of && or ||, has a true and a false outcome; branch coverage is the share of outcomes that happened. match arms are measured as regions, not branches, so code built on match can show no branches but still have its arms checked by region coverage.']
    ]);
    section('Source view', [
      ['Count column', 'How many times the line ran: green if it ran, red if it never did; empty for lines with no code (comments, declarations, Verus specs).'],
      ['Line background', 'Green: everything on the line ran. Yellow: the line ran, but a branch outcome was never taken or a region on it never executed. Red: the line never ran.'],
      ['Red code', 'A region of an executed line that never ran (e.g. the body of an if whose condition was never true).'],
      [':col  T n  F n', 'One group per condition on the line: the column where the condition starts, then how often it was true (T) and false (F). Red: that outcome never happened. Grey: the condition was never evaluated.']
    ]);
    section('Tables', [
      ['Colours', 'Green: 90 % or more. Yellow: 75 % or more. Red: below 75 %.'],
      ['Sorting', 'Click a column title to sort lowest first; click again to reverse. Rows without data (–) stay last.'],
      ['Totals', 'The whole directory (or, at the top level, everything in the report: one crate, or several merged, a file they share counted once).']
    ]);
    box.appendChild(el('p', 'gl-help-note',
      'Measured by rustc\'s coverage instrumentation (-Cinstrument-coverage -Zcoverage-options=branch) and LLVM\'s llvm-cov.'));
    overlay.appendChild(box);
    function hide(ev) { if (ev) ev.preventDefault(); overlay.remove(); document.removeEventListener('keydown', esc); }
    function esc(ev) { if (ev.key === 'Escape') hide(); }
    close.addEventListener('click', hide);
    overlay.addEventListener('click', function (ev) { if (ev.target === overlay) hide(); });
    document.addEventListener('keydown', esc);
    document.body.appendChild(overlay);
  }

  // ---- page frame: breadcrumb (with Help), content, footer ----
  function frame(crumbs, nodes) {
    app.innerHTML = '';
    var page = el('div', 'gl-page');
    var bar = el('div', 'gl-crumbs');
    var help = link('Help', '#', 'gl-help-link');
    help.addEventListener('click', function (ev) { ev.preventDefault(); helpPanel(); });
    bar.appendChild(help);
    crumbs.forEach(function (c) {
      var s = el('span', c[1] ? '' : 'gl-here');
      if (c[1]) s.appendChild(link(c[0], c[1])); else s.textContent = c[0];
      bar.appendChild(s);
    });
    page.appendChild(bar);
    nodes.forEach(function (n) { page.appendChild(n); });
    app.appendChild(page);
    var footer = el('div', 'gl-footer', date ? 'Date: ' + date : '');
    if (C.crate) {
      footer.appendChild(el('br')); footer.appendChild(el('br'));
      footer.appendChild(document.createTextNode((C.crate.indexOf(', ') < 0 ? 'Crate: ' : 'Crates: ') + C.crate));
    }
    app.appendChild(footer);
  }
  function dirHref(d) { return '#dir=' + encodeURIComponent(d); }
  function fileHref(p, line) { return '#file=' + encodeURIComponent(p) + (line ? '&line=' + line : ''); }

  // ---- listing (top level, directory) ----
  function listing(nameLabel, rows, totals) {
    var table = el('table', 'gl-table');
    var head = el('tr');
    var state = { key: null, ascending: true };
    function sortBy(key, a) {
      state.ascending = state.key === key ? !state.ascending : true;
      state.key = key;
      var body = Array.prototype.filter.call(table.querySelectorAll('tr'), function (r) { return r.hasAttribute('data-name'); });
      body.sort(function (x, y) {
        var p = x.getAttribute('data-' + key), q = y.getAttribute('data-' + key);
        if (key === 'name') return (state.ascending ? 1 : -1) * p.localeCompare(q);
        var pn = p === '', qn = q === '';
        if (pn || qn) return pn === qn ? 0 : pn ? 1 : -1;
        return (state.ascending ? 1 : -1) * (+p - +q);
      });
      var tot = table.querySelector('tr.gl-totals');
      body.forEach(function (r) { table.insertBefore(r, tot); });
      head.querySelectorAll('.gl-arrow').forEach(function (e) { e.textContent = ''; });
      a.querySelector('.gl-arrow').textContent = state.ascending ? ' ▲' : ' ▼';
    }
    function sortHeader(th, key, label) {
      var a = link(label, '#');
      a.appendChild(el('span', 'gl-arrow'));
      a.addEventListener('click', function (ev) { ev.preventDefault(); sortBy(key, a); });
      th.appendChild(a);
    }
    var th0 = el('th'); th0.colSpan = 2; sortHeader(th0, 'name', nameLabel); head.appendChild(th0);
    METRICS.forEach(function (m) {
      var th = el('th'); th.colSpan = 2; sortHeader(th, m[0], m[0] === 'line' ? 'Line Coverage' : m[1]);
      th.setAttribute('data-tip', HELP[m[0]]);
      head.appendChild(th);
    });
    table.appendChild(head);

    function cells(tr, m) {
      METRICS.forEach(function (k) {
        var hc = m[k[0]], p = pct(hc[0], hc[1]);
        if (isNaN(p)) { tr.appendChild(el('td', 'gl-na', '–')); tr.appendChild(el('td', 'gl-na', '')); }
        else {
          tr.appendChild(el('td', 'gl-' + level(p), p + '%'));
          tr.appendChild(el('td', 'gl-' + level(p), hc[0] + ' / ' + hc[1]));
        }
      });
    }
    rows.forEach(function (r) {
      var tr = el('tr');
      tr.setAttribute('data-name', r.name);
      METRICS.forEach(function (k) { var p = pct(r.m[k[0]][0], r.m[k[0]][1]); tr.setAttribute('data-' + k[0], isNaN(p) ? '' : p); });
      var name = el('td', 'gl-name'); name.appendChild(link(r.name, r.href)); tr.appendChild(name);
      var pillCell = el('td', 'gl-pill-cell');
      var lp = pct(r.m.line[0], r.m.line[1]);
      if (!isNaN(lp)) {
        var pill = el('div', 'gl-pill'), fill = el('div');
        fill.style.height = lp + '%'; fill.style.background = 'var(--gl-' + level(lp) + ')';
        pill.setAttribute('data-tip', 'line coverage ' + lp + ' %');
        pill.appendChild(fill); pillCell.appendChild(pill);
      }
      tr.appendChild(pillCell);
      cells(tr, r.m);
      table.appendChild(tr);
    });
    var tot = el('tr', 'gl-totals');
    tot.appendChild(el('td', 'gl-name', 'Totals'));
    tot.appendChild(el('td', 'gl-pill-cell'));
    cells(tot, totals);
    table.appendChild(tot);
    return table;
  }

  function showTop() {
    var rows = Object.keys(dirs).sort().map(function (d) {
      return { name: d + '/', href: dirHref(d), m: total(dirs[d]) };
    });
    frame([['top_level']], [listing('Directory', rows, total(files))]);
  }

  function showDir(d) {
    var fs = (dirs[d] || []).slice().sort(function (x, y) { return x.name.localeCompare(y.name); });
    var rows = fs.map(function (f) { return { name: f.name, href: fileHref(f.path), m: f.m }; });
    frame([['top_level', '#'], [d]], [listing('File', rows, total(fs))]);
  }

  // ---- source view ----
  function tip(side, n) { return side + ' branch ' + (n > 0 ? 'taken ' + n + ' time' + (n === 1 ? '' : 's') : 'never taken'); }

  function showFile(f, target) {
    // header: file, directory, date on the left; Coverage / Hit / Total on the right
    var header = el('div', 'gl-header');
    var info = el('table', 'gl-info');
    [['File:', f.name], ['Directory:', link(f.dir, dirHref(f.dir))], ['Test Date:', date]].forEach(function (r) {
      if (!r[1]) return;
      var tr = el('tr'); tr.appendChild(el('th', '', r[0]));
      var td = el('td'); if (typeof r[1] === 'string') td.textContent = r[1]; else td.appendChild(r[1]);
      tr.appendChild(td); info.appendChild(tr);
    });
    header.appendChild(info);
    var sum = el('table', 'gl-summary');
    var sh = el('tr'); ['', 'Coverage', 'Hit', 'Total'].forEach(function (h) { sh.appendChild(el('th', '', h)); });
    sum.appendChild(sh);
    METRICS.forEach(function (m) {
      var hc = f.m[m[0]], p = pct(hc[0], hc[1]);
      var tr = el('tr');
      var th = el('th', 'gl-metric', m[1] + ':'); th.setAttribute('data-tip', HELP[m[0]]); tr.appendChild(th);
      if (isNaN(p)) { tr.appendChild(el('td', 'gl-na gl-rate', '–')); tr.appendChild(el('td', 'gl-na', '0')); tr.appendChild(el('td', 'gl-na', '0')); }
      else {
        tr.appendChild(el('td', 'gl-' + level(p) + ' gl-rate', p + ' %'));
        tr.appendChild(el('td', '', String(hc[0])));
        tr.appendChild(el('td', '', String(hc[1])));
      }
      sum.appendChild(tr);
    });
    header.appendChild(sum);

    var content = el('div', 'gl-source');
    var lines = f.src.split(/\r?\n/);
    if (lines.length && lines[lines.length - 1] === '') lines.pop();
    lines.forEach(function (code, i) {
      var num = i + 1;
      var count = f.lines.hasOwnProperty(num) ? String(f.lines[num]) : '';
      var row = el('div', 'gl-row');
      row.id = 'L' + num;
      var ln = el('div', 'gl-ln'); ln.appendChild(link(String(num), fileHref(f.path, num))); row.appendChild(ln);
      row.appendChild(el('div', 'gl-count', count));

      // branch column: one group per branch -- ":col", then the T and F pills
      var br = el('div', 'gl-br');
      var anyNot = false;
      (f.br[num] || []).forEach(function (b) {
        var col = b[1], t = b[4], fl = b[5];
        var where = 'Branch (' + num + ':' + col + '): ';
        var reached = t > 0 || fl > 0;
        var grp = el('span', 'gl-bgrp');
        var pos = el('span', 'gl-pos', ':' + col);
        pos.setAttribute('data-tip', where + 'columns ' + col + '–' + b[3] + (b[2] !== num ? ' (to line ' + b[2] + ')' : ''));
        grp.appendChild(pos);
        [['T', 'true', t], ['F', 'false', fl]].forEach(function (s) {
          var pill = el('span', 'gl-tf ' + (!reached ? 'gl-unreached' : s[2] > 0 ? 'gl-taken' : 'gl-not'), s[0] + ' ' + s[2]);
          pill.setAttribute('data-tip', where + (reached ? tip(s[1], s[2]) : 'not reached (condition never evaluated)'));
          grp.appendChild(pill);
        });
        if (reached && (t === 0 || fl === 0)) anyNot = true;
        br.appendChild(grp);
      });
      row.appendChild(br);

      // code: never-executed regions of an executed line marked; a wrapped line
      // continues under its own indentation plus 4 columns (a hanging indent)
      var leadRaw = /^[ \t]*/.exec(code)[0];
      var body = code.slice(leadRaw.length);
      var zeros = [];
      if (f.z[num] && count !== '' && count !== '0') {
        f.z[num].forEach(function (z) {
          var s = Math.max(z[0] - 1 - leadRaw.length, 0);
          var e = (z[1] === 0 ? code.length : z[1] - 1) - leadRaw.length;
          if (e > s && body.slice(s, e).trim() !== '') zeros.push([s, e, z[0]]);
        });
        zeros.sort(function (x, y) { return x[0] - y[0]; });
      }
      var codeEl = el('div', 'gl-code');
      var at = 0;
      zeros.forEach(function (z) {
        if (z[0] < at) return;
        if (z[0] > at) codeEl.appendChild(document.createTextNode(body.slice(at, z[0])));
        var span = el('span', 'gl-zero', body.slice(z[0], z[1]));
        span.setAttribute('data-tip', 'Region (' + num + ':' + z[2] + '): never executed');
        codeEl.appendChild(span);
        at = z[1];
      });
      codeEl.appendChild(document.createTextNode(body.slice(at)));
      var lead = leadRaw.replace(/\t/g, '    ').length;
      codeEl.style.paddingLeft = 'calc(8px + ' + (lead + 4) + 'ch)';
      codeEl.style.textIndent = '-4ch';
      row.appendChild(codeEl);

      if (count === '0') row.className += ' gl-miss';
      else if (count !== '') row.className += ' gl-hit' + (anyNot || zeros.length ? ' gl-partial' : '');
      if (target === num) row.className += ' gl-target';
      content.appendChild(row);
    });
    frame([['top_level', '#'], [f.dir, dirHref(f.dir)], [f.name]], [header, content]);
    if (target) { var t = document.getElementById('L' + target); if (t) t.scrollIntoView({ block: 'center' }); }
    else window.scrollTo(0, 0);
  }

  // ---- routing ----
  function route() {
    var h = location.hash.replace(/^#/, '');
    var q = {};
    h.split('&').forEach(function (kv) { var i = kv.indexOf('='); if (i > 0) q[kv.slice(0, i)] = decodeURIComponent(kv.slice(i + 1)); });
    if (q.file && byPath[q.file]) showFile(byPath[q.file], q.line ? +q.line : 0);
    else if (q.dir && dirs[q.dir]) { showDir(q.dir); window.scrollTo(0, 0); }
    else { showTop(); window.scrollTo(0, 0); }
  }
  window.addEventListener('hashchange', route);
  route();
})();
